-- Avante organizado igual às pastas do canal Avante Soluções Digitais (tutoriais).
DELETE l FROM lessons l JOIN modules m ON m.module_id = l.module_id WHERE m.system_id = 'avante' AND l.origin = 'demo' AND l.video_source = 'none';
DELETE m FROM modules m WHERE m.system_id = 'avante' AND m.name NOT IN ('Cadastros','Faturamento','Frente de Caixa - PDV','Financeiro','Parametrização de Documentos Fiscais','Emissão de Documentos Fiscais','Rejeições Fiscais','SEUPOS') AND NOT EXISTS (SELECT 1 FROM lessons l WHERE l.module_id = m.module_id);
UPDATE modules SET position = 1, icon = 'file' WHERE system_id = 'avante' AND name = 'Cadastros';
UPDATE modules SET position = 2, icon = 'cart' WHERE system_id = 'avante' AND name = 'Faturamento';
UPDATE modules SET position = 3, icon = 'card' WHERE system_id = 'avante' AND name = 'Frente de Caixa - PDV';
UPDATE modules SET position = 4, icon = 'cash' WHERE system_id = 'avante' AND name = 'Financeiro';
UPDATE modules SET position = 5, icon = 'sliders' WHERE system_id = 'avante' AND name = 'Parametrização de Documentos Fiscais';
UPDATE modules SET position = 6, icon = 'receipt' WHERE system_id = 'avante' AND name = 'Emissão de Documentos Fiscais';
UPDATE modules SET position = 7, icon = 'shield' WHERE system_id = 'avante' AND name = 'Rejeições Fiscais';
UPDATE modules SET position = 8, icon = 'plug' WHERE system_id = 'avante' AND name = 'SEUPOS';
UPDATE modules SET position = position + 100 WHERE system_id = 'avante' AND name NOT IN ('Cadastros','Faturamento','Frente de Caixa - PDV','Financeiro','Parametrização de Documentos Fiscais','Emissão de Documentos Fiscais','Rejeições Fiscais','SEUPOS');
UPDATE systems SET description = 'Gestão comercial com cadastros, faturamento, frente de caixa, financeiro e emissão de documentos fiscais.' WHERE system_id = 'avante';
